class Student:
    def __init__(self, name, form):
        self.name = name
        self.form = form
        self.scores = {}

    def add_score(self, subject, score):
        self.scores[subject] = score

    def average(self):
        if not self.scores:
            return 0
        return round(sum(self.scores.values()) / len(self.scores), 1)

