class Vehicle:
    def __init__(self, plate, seats):
        self.plate = plate
        self.seats = seats
        self._passengers = 0      # change it only through board()

    def board(self, n=1):
        if self._passengers + n > self.seats:
            return "Full! Wait for the next one."
        self._passengers += n
        return f"{n} boarded. {self.seats - self._passengers} seats left."
    def __str__(self):
        return f"{type(self).__name__} {self.plate}"

class Danfo(Vehicle):
    def __init__(self, plate):
        super().__init__(plate, seats=14)
    def call_out(self):
        return "Ilaro! Ilaro! Enter with your change!"

bus = Danfo("OG-123-XY")
print(bus, "-", bus.call_out())
print(bus.board(10))
print(bus.board(5))

