from flask import Flask, render_template_string, request
app = Flask(__name__)
scores = []      # practice only: lost when the server stops
PAGE = '''
<form method="post">
  <input name="subject" placeholder="Subject" required>
  <input name="score" type="number" min="0" max="100" required>
  <button>Add</button>
</form><p>{{ msg }}</p>
{% for s in scores %}<p>{{ s.subject }}: {{ s.score }}</p>{% endfor %}
'''

@app.route("/", methods=["GET", "POST"])
def home():
    msg = ""
    if request.method == "POST":
        score = request.form.get("score", "")
        if score.isdigit() and int(score) <= 100:
            scores.append({"subject": request.form["subject"], "score": int(score)})
        else:
            msg = "Score must be a number from 0 to 100."
    return render_template_string(PAGE, scores=scores, msg=msg)

if __name__ == "__main__":
    app.run(debug=True)
